#!/usr/bin/env bash
# Master script: applies all priest-removal code changes, adds the DB
# migration file, and prints the commit/push + DB migration commands.
# Run from the ROOT of your diocesan-finance-api repo in Codespaces.
set -euo pipefail

if [ ! -f "package.json" ] || [ ! -d "src/graphql" ]; then
  echo "ERROR: run this from the root of the diocesan-finance-api repo." >&2
  exit 1
fi

echo "Removing src/utils/priestTokens.js ..."
rm -f src/utils/priestTokens.js

mkdir -p client/src/components/layout client/src/graphql client/src/pages src/graphql src/services migrations

echo "Writing client/src/components/layout/AppLayout.jsx ..."
mkdir -p "client/src/components/layout"
base64 -d > "client/src/components/layout/AppLayout.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/components/layout/MobileSidebar.jsx ..."
mkdir -p "client/src/components/layout"
base64 -d > "client/src/components/layout/MobileSidebar.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/components/layout/Sidebar.jsx ..."
mkdir -p "client/src/components/layout"
base64 -d > "client/src/components/layout/Sidebar.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/graphql/queries.js ..."
mkdir -p "client/src/graphql"
base64 -d > "client/src/graphql/queries.js" << 'B64EOF'

B64EOF

echo "Writing client/src/pages/Login.jsx ..."
mkdir -p "client/src/pages"
base64 -d > "client/src/pages/Login.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/pages/ParishDetail.jsx ..."
mkdir -p "client/src/pages"
base64 -d > "client/src/pages/ParishDetail.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/pages/Remittances.jsx ..."
mkdir -p "client/src/pages"
base64 -d > "client/src/pages/Remittances.jsx" << 'B64EOF'

B64EOF

echo "Writing client/src/pages/Users.jsx ..."
mkdir -p "client/src/pages"
base64 -d > "client/src/pages/Users.jsx" << 'B64EOF'

B64EOF

echo "Writing schema.sql ..."
mkdir -p "."
base64 -d > "schema.sql" << 'B64EOF'

B64EOF

echo "Writing src/graphql/resolvers.js ..."
mkdir -p "src/graphql"
base64 -d > "src/graphql/resolvers.js" << 'B64EOF'

B64EOF

echo "Writing src/graphql/typeDefs.js ..."
mkdir -p "src/graphql"
base64 -d > "src/graphql/typeDefs.js" << 'B64EOF'

B64EOF

echo "Writing src/server.js ..."
mkdir -p "src"
base64 -d > "src/server.js" << 'B64EOF'

B64EOF

echo "Writing src/services/spreadsheetParser.js ..."
mkdir -p "src/services"
base64 -d > "src/services/spreadsheetParser.js" << 'B64EOF'

B64EOF

echo "Writing migrations/001_revoke_priest_access.sql ..."
base64 -d > migrations/001_revoke_priest_access.sql << 'B64EOF'

B64EOF

echo ""
echo "All code changes applied and migration file written."
echo ""
echo "Next steps:"
echo "  1. Review the changes:      git status && git diff --stat"
echo "  2. Run the DB migration against your LIVE Render DB first:"
echo '       psql "$DATABASE_URL" -f migrations/001_revoke_priest_access.sql'
echo "     (DATABASE_URL is the connection string from your Render dashboard.)"
echo "  3. Commit and push:"
echo "       git add -A"
echo "       git commit -m 'Remove priest login accounts, tokens, and UI access'"
echo "       git push origin main"
